import java.util.Scanner;

public class CF_723B {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        String inputString = scanner.next();

        String pattern = "\\([a-zA-Z_]*\\)";
        String replacedInput = inputString.replaceAll(pattern, "_");

        String[] splitParts = replacedInput.split("_+");
        int maxPartSize = 0;
        for (String part : splitParts) {
            maxPartSize = Math.max(maxPartSize, part.length());
        }
        System.out.println(maxPartSize);

        int countInParentheses = 0;
        boolean insideParentheses = false;
        int startIdx = -1, endIdx = -1;
        for (int i = 0; i < inputString.length(); i++) {
            char c = inputString.charAt(i);
            if (c == '(') {
                insideParentheses = true;
                startIdx = i;
            } else if (c == ')' && insideParentheses) {
                insideParentheses = false;
                endIdx = i;
                String innerContent = inputString.substring(startIdx + 1, endIdx);
                if (!innerContent.isEmpty()) {
                    String[] segments = innerContent.split("_+");
                    countInParentheses += segments.length - (innerContent.startsWith("_") ? 1 : 0);
                }
            }
        }
        System.out.println(countInParentheses);
    }
}
